// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    $bahanJenisId = $('#bahan_jenis_id'),
    formCek = CirebonwebForm.FormCek($formData);

// Mengambil jenis bahan berdasarkan tipe mesin
function loadBahanJenis(mesinTipeId, selectedId, callback) {
    $bahanJenisId.prop('disabled', true).prop('required', Boolean(mesinTipeId)).empty().append('<option value="">-- Pilih --</option>');
    aturStatusFormBahan();

    if (!mesinTipeId) {
        $bahanJenisId.val('').trigger('change');
        if (callback) callback();
        return;
    }

    $.post(`${urlThis}/getbahanjenis`, { mesinTipeId: mesinTipeId }, function (rows) {
        rows.forEach(function (row) {
            $bahanJenisId.append(`<option value="${row.id}" data-rumus="${row.rumus}">${row.nama}</option>`);
        });

        $bahanJenisId.prop('disabled', false).val(selectedId || '').trigger('change');
        if (callback) callback();
    }).fail(function () {
        Swal.fire({ icon: 'error', title: 'Error', text: 'Gagal memuat jenis bahan. Silakan coba lagi.'});
    });
}

function aturStatusFormBahan() {
    const aktif = Boolean($bahanJenisId.val());

    $('#kode, #nama, #lebar, #panjang, #isi_paket, #satuan_1, #satuan_2').prop('disabled', !aktif);
    $('#btnSubmit').prop('disabled', !aktif);
}

/**
 * Validasi dimensiBahan berdasarkan rumus
 * Rumus diambil dari jenis bahan yang dipilih (bahan_jenis.rumus)
 * @returns {'0'|'1'|null}
 */
function rumusTerpilih() {
    const rumus = $bahanJenisId.find(':selected').data('rumus');

    if (!$bahanJenisId.val() || rumus === undefined) {
        return null;
    }

    return String(rumus) === '1' ? '1' : '0';
}

if (typeof $.validator !== 'undefined') {
    $.validator.addMethod('dimensiBahan', function (value, element) {
        let nilai = Number(String(value).replace(',', '.')),
            nilaiMinimum = rumusTerpilih() === '0' ? 0.1 : 0;

        return this.optional(element) || (!Number.isNaN(nilai) && nilai >= nilaiMinimum);
    }, 'perkalian luas minimal 0.1');
}

/**
 * Logika Utama Kalkulasi dan Pengaturan UI Form Bahan
 */
function aturKonsepBahan(resetIsiPaket = false) {
    let valRumus = rumusTerpilih(),
        lebarVal = $('#lebar').val() || 0,
        panjangVal = $('#panjang').val() || 0,
        $isiPaket = $('#isi_paket'),
        satuan1Val = $('#satuan_1').val() || '',
        satuan2Val = $('#satuan_2').val() || '';

    // 1. Update text append pada input luas
    $('.satuan1').text(satuan1Val);

    if (valRumus === null) {
        $('.satuan2').text(`1 ${satuan2Val} = ${$isiPaket.val() || 0} ${satuan1Val}`);
        return;
    }

    // 2. Handling berdasarkan Rumus
    if (valRumus === "0") {
        // Mode: Perkalian Luas (Hitung Otomatis)
        $isiPaket.prop('readonly', true);
        let totalLuas = lebarVal * panjangVal;
        $isiPaket.val(totalLuas.toFixed(2));
    } else {
        // Mode: Perkalian Qty (Input Manual oleh User)
        $isiPaket.prop('readonly', false);
        if (resetIsiPaket) {
            $isiPaket.val('0');
        }
    }

    // 3. Update Label Satuan 2 (Format: "1 [satuan_2] = [luas/qty] [satuan_1]")
    let luasVal = $isiPaket.val() || 0;
    $('.satuan2').text(`1 ${satuan2Val} = ${luasVal} ${satuan1Val}`);
}

// DataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`, type: 'POST',
            data: function (d) {
                d.filter_tipe = $('#filter_tipe').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => { simpan(); } },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_tipe').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 8], className: 'dt-body-center' },
            { targets: [4, 5], className: 'dt-body-right' },
            { targets: [9, 10], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data) } },
            { targets: [4, 5, 6, 7, 8], orderable: false },
        ]
    });

    $('#tabelData_filter.dataTables_filter').append($('#filter_tipe'));
    $(document).on('change', '#filter_tipe', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    })

    // Modal Event Listeners (Auto focus search Select2)
    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    // Event Listener Realtime Perubahan Form
    $bahanJenisId.on('change', function () {
        aturStatusFormBahan();
        aturKonsepBahan(true);
    });

    $('#satuan_1, #satuan_2').on('change', aturKonsepBahan);

    $('#lebar, #panjang, #isi_paket').on('input change', function () {
        aturKonsepBahan();
    });

    $('#mesin_tipe_id').on('change', function (event, selectedBahanId) {
        loadBahanJenis($(this).val(), selectedBahanId);
    });

    // Reset Modal Event
    aturStatusFormBahan();
    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ dropdownParent: $modalDiv });

        // Jalankan sinkronisasi UI saat modal terbuka
        aturStatusFormBahan();
        aturKonsepBahan();
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $bahanJenisId.prop('disabled', true);
        aturStatusFormBahan();
        $('.select2.select2-hidden-accessible').select2('destroy');

        // Reset label ke tampilan awal
        $('.satuan2').text('1 roll = 0 m²');
        $('.satuan1').text('m²');
    });
});

// Form Submit (Insert/Update)
function simpan(id) {
    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${urlThis}/simpan`;

    // Tentukan URL POST: Simpan atau Update
    if (id > 0) {
        // CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {})
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {}).done(function (res) {
            if (!res.success) return;
            // .done(function (res) {
            // if (res.success) {
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');

            // Populate Data
            $formData.find('#id').val(res.data.id);
            $formData.find('#kode').val(res.data.kode);
            $formData.find('#nama').val(res.data.nama);
            $formData.find('#isi_paket').val(CirebonwebFormat.Desimal(res.data.isi_paket));
            $formData.find('#lebar').val(CirebonwebFormat.Desimal(res.data.lebar));
            $formData.find('#panjang').val(CirebonwebFormat.Desimal(res.data.panjang));

            // Trigger Select2
            $formData.find('#satuan_1').val(res.data.satuan_1);
            $formData.find('#satuan_2').val(res.data.satuan_2);

            // Trigger tipe mesin
            const mesinTipeId = res.data.mesin_tipe_id;
            $formData.find('#mesin_tipe_id').val(mesinTipeId);
            $formData.find('#bahan_jenis_id').val(res.data.bahan_jenis_id);
            loadBahanJenis(mesinTipeId, res.data.bahan_jenis_id, function () {
                $formData.find('#isi_paket').val(CirebonwebFormat.Desimal(res.data.isi_paket));
                aturKonsepBahan();
                $modalDiv.modal('show');
            });
            // }
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $modalDiv.modal('show');
    }

    // Form Validasi
    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            bahan_jenis_id: { required: true, digits: true },
            kode: { required: true, minlength: 2, maxlength: 30 },
            nama: { required: true, minlength: 3, maxlength: 100 },
            lebar: { required: true, maxlength: 8, dimensiBahan: true },
            panjang: { required: true, maxlength: 8, dimensiBahan: true },
            isi_paket: { required: true, maxlength: 10 },
            satuan_1: { required: true, maxlength: 10 },
            satuan_2: { required: true, maxlength: 10 },
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            })
                .done(function (response) {
                    if (!response.success) return;
                    $modalDiv.modal('hide');
                    Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                        .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
                });
            return false;
        }
    }));
}

// Form Submit (Delete)
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${urlThis}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}